using System.Collections.Immutable;
using Benchmark.Frontend.Api;
using Benchmark.Frontend.Store;
using Fluxor;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
namespace Benchmark.Frontend.Tests;
public sealed class EffectTests
{
    [Fact] public async Task Login_effect_calls_API_then_loads_with_returned_token(){using var h=new StoreHarness();h.Api.Items=[new(Guid.NewGuid(),"Existing","Todo",1)];await h.Login();Assert.Contains(h.Api.Calls,c=>c.Method=="LOGIN"&&c.Title=="alice@example.test");Assert.Contains(h.Api.Calls,c=>c.Method=="GET"&&c.Token=="test-token");Assert.Single(h.State.Value.Items);}
    [Fact] public async Task Failed_login_has_error_without_private_session(){using var h=new StoreHarness();h.Dispatcher.Dispatch(new LoginRequested(Guid.NewGuid(),"alice@example.test","wrong"));await StoreHarness.Until(()=>h.State.Value.Error!=null);Assert.Null(h.State.Value.AccessToken);Assert.Empty(h.State.Value.Items);Assert.False(h.State.Value.Pending);}
    [Fact] public async Task Load_remains_pending_until_response_then_replaces_items(){using var h=new StoreHarness();await h.Login();h.Api.ListGate=new(TaskCreationOptions.RunContinuationsAsynchronously);h.Dispatcher.Dispatch(new LoadRequested(Guid.NewGuid()));Assert.True(h.State.Value.Pending);var item=new WorkItemView(Guid.NewGuid(),"Loaded","Done",3);h.Api.ListGate.SetResult([item]);await StoreHarness.Until(()=>!h.State.Value.Pending);Assert.Equal(new[]{item},h.State.Value.Items.ToArray());}
    [Fact] public async Task Add_effect_sends_selected_status_and_refreshes_authoritative_items(){using var h=new StoreHarness();await h.Login();h.Dispatcher.Dispatch(new AddRequested(Guid.NewGuid(),"New","InProgress"));await StoreHarness.Until(()=>h.State.Value.Items.Length==1&&!h.State.Value.Pending);Assert.Contains(h.Api.Calls,c=>c.Method=="POST"&&c.Token=="test-token"&&c.Title=="New"&&c.Status=="InProgress");Assert.Equal(1,h.State.Value.Items[0].Version);}
    [Fact] public async Task Update_effect_sends_current_version_and_reloads(){using var h=new StoreHarness();var item=new WorkItemView(Guid.NewGuid(),"Old","Todo",4);h.Api.Items=[item];await h.Login();h.Dispatcher.Dispatch(new UpdateRequested(Guid.NewGuid(),item.Id,"New","Done",4));await StoreHarness.Until(()=>h.State.Value.Items[0].Version==5&&!h.State.Value.Pending);Assert.Contains(h.Api.Calls,c=>c.Method=="PUT"&&c.Id==item.Id&&c.ExpectedVersion==4&&c.Token=="test-token");}
    [Fact] public async Task Delete_effect_sends_expected_version_then_refreshes(){using var h=new StoreHarness();var item=new WorkItemView(Guid.NewGuid(),"Old","Todo",4);h.Api.Items=[item];await h.Login();h.Dispatcher.Dispatch(new DeleteRequested(Guid.NewGuid(),item.Id,4));await StoreHarness.Until(()=>h.State.Value.Items.IsEmpty&&!h.State.Value.Pending);Assert.Contains(h.Api.Calls,c=>c.Method=="DELETE"&&c.Id==item.Id&&c.ExpectedVersion==4&&c.Token=="test-token");}
    [Fact] public async Task Conflict_preserves_previous_items_without_automatic_retry(){using var h=new StoreHarness();h.Api.Items=[new(Guid.NewGuid(),"Old","Todo",1)];await h.Login();h.Api.FailureStatus=409;h.Dispatcher.Dispatch(new AddRequested(Guid.NewGuid(),"Never added","Todo"));await StoreHarness.Until(()=>h.State.Value.Error!=null&&!h.State.Value.Pending);Assert.Equal("Old",h.State.Value.Items.Single().Title);Assert.Equal(1,h.Api.Calls.Count(c=>c.Method=="POST"));}
    [Fact] public async Task Unauthorized_operation_clears_private_state(){using var h=new StoreHarness();h.Api.Items=[new(Guid.NewGuid(),"Private","Todo",1)];await h.Login();h.Api.FailureStatus=401;h.Dispatcher.Dispatch(new LoadRequested(Guid.NewGuid()));await StoreHarness.Until(()=>h.State.Value.AccessToken==null);Assert.Empty(h.State.Value.Items);Assert.False(h.State.Value.Pending);}
    [Fact] public async Task Logout_while_login_is_pending_rejects_late_login(){using var h=new StoreHarness();h.Api.LoginGate=new(TaskCreationOptions.RunContinuationsAsynchronously);h.Dispatcher.Dispatch(new LoginRequested(Guid.NewGuid(),"alice@example.test","Alice!234"));Assert.True(h.State.Value.Pending);h.Dispatcher.Dispatch(new LogoutRequested());h.Api.LoginGate.SetResult("late-token");await Task.Delay(50);Assert.Null(h.State.Value.AccessToken);Assert.Empty(h.State.Value.Items);Assert.DoesNotContain(h.Api.Calls,c=>c.Method=="GET");}
    [Fact] public async Task Logout_while_read_is_pending_rejects_late_items(){using var h=new StoreHarness();await h.Login();h.Api.ListGate=new(TaskCreationOptions.RunContinuationsAsynchronously);h.Dispatcher.Dispatch(new LoadRequested(Guid.NewGuid()));Assert.True(h.State.Value.Pending);h.Dispatcher.Dispatch(new LogoutRequested());h.Api.ListGate.SetResult([new(Guid.NewGuid(),"Late private","Done",1)]);await Task.Delay(50);Assert.Null(h.State.Value.AccessToken);Assert.Empty(h.State.Value.Items);}
    [Fact] public async Task Pending_duplicate_submit_does_not_issue_second_HTTP_effect(){using var h=new StoreHarness();await h.Login();h.Api.AddGate=new(TaskCreationOptions.RunContinuationsAsynchronously);h.Dispatcher.Dispatch(new AddRequested(Guid.NewGuid(),"First","Todo"));h.Dispatcher.Dispatch(new AddRequested(Guid.NewGuid(),"Second","Todo"));Assert.True(h.State.Value.Pending);Assert.Single(h.Api.Calls,c=>c.Method=="POST");h.Dispatcher.Dispatch(new LogoutRequested());h.Api.AddGate.SetResult(new(Guid.NewGuid(),"First","Todo",1));await Task.Delay(30);Assert.Empty(h.State.Value.Items);}
    [Fact] public async Task Fluxor_stores_are_scoped_per_circuit(){var services=new ServiceCollection();services.AddSingleton<IWorkItemApi>(new FakeApi());services.AddLogging();services.AddFluxor(o=>o.ScanAssemblies(typeof(BoardState).Assembly).WithLifetime(StoreLifetime.Scoped));using var p=services.BuildServiceProvider();using var a=p.CreateScope();using var b=p.CreateScope();var sa=a.ServiceProvider.GetRequiredService<IState<BoardState>>();var sb=b.ServiceProvider.GetRequiredService<IState<BoardState>>();Assert.NotSame(sa,sb);await a.ServiceProvider.GetRequiredService<IStore>().InitializeAsync();await b.ServiceProvider.GetRequiredService<IStore>().InitializeAsync();a.ServiceProvider.GetRequiredService<IDispatcher>().Dispatch(new LoginRequested(Guid.NewGuid(),"alice@example.test","Alice!234"));await StoreHarness.Until(()=>sa.Value.AccessToken=="test-token");Assert.Null(sb.Value.AccessToken);Assert.Empty(sb.Value.Items);}
}


